import unittest
from src.cors import get_cors_headers
class TestCORS(unittest.TestCase):
    def test_cors(self):
        h1 = get_cors_headers('https://evil.com')
        self.assertNotEqual(h1.get('Access-Control-Allow-Origin'), '*')
        h2 = get_cors_headers('https://example.com')
        self.assertEqual(h2.get('Access-Control-Allow-Origin'), 'https://example.com')
