import unittest
from src.webhook import is_safe_webhook_url
class TestSSRF(unittest.TestCase):
    def test_block_internal(self):
        self.assertFalse(is_safe_webhook_url('http://127.0.0.1:8080/admin'))
        self.assertFalse(is_safe_webhook_url('http://localhost/secret'))
        self.assertFalse(is_safe_webhook_url('http://192.168.1.1/router'))
        self.assertTrue(is_safe_webhook_url('https://api.github.com/hook'))
if __name__ == '__main__':
    unittest.main()

